package org.humanjourney.core.progress.client;
import java.util.*;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.components.Button;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.world.item.*;
import net.minecraft.util.FormattedCharSequence;
import org.humanjourney.core.progress.*;
import org.lwjgl.glfw.GLFW;
/** One tab and one continuous canvas; read-only selection, never an unlock action. */
public final class ProgressScreen extends Screen {
 private final Screen parent;private final ProgressCanvas.Viewport camera=new ProgressCanvas.Viewport();private ProgressCanvas.Layout layout;private ProgressView observed;private String selected="",activeTab=ProgressCanvas.TABS.getFirst();private boolean fitted,dragging;private int detailScroll,detailMax;
 public ProgressScreen(Screen parent){super(Component.literal("Civilization Progress"));this.parent=parent;}
 @Override protected void init(){layout=ProgressCanvas.Layout.of(width,height);int tabWidth=Math.max(80,Math.min(216,(width-120)/ProgressCanvas.TABS.size()));int tabX=8;for(String tab:ProgressCanvas.TABS){final String id=tab;addRenderableWidget(Button.builder(Component.literal(id.equals("civilization_progress")?"Civilization Progress":id),button->{activeTab=id;rebuildWidgets();}).bounds(tabX,8,tabWidth,20).build());tabX+=tabWidth+4;}addRenderableWidget(Button.builder(Component.literal("Fit"),b->{camera.fit();}).bounds(Math.max(8,width-98),8,38,20).build());addRenderableWidget(Button.builder(Component.literal("Back"),b->onClose()).bounds(Math.max(48,width-56),8,48,20).build());}
 @Override public boolean isPauseScreen(){return false;}
 @Override public void onClose(){minecraft.setScreen(parent);}
 private void update(){var view=ProgressClient.STATE.view();if(view!=observed){if(view.nodes().stream().noneMatch(n->n.id().equals(selected)))selected="";observed=view;}camera.configure(layout.canvas(),ProgressCanvas.bounds(view));if(!fitted&&!view.nodes().isEmpty()){camera.start();fitted=true;}}
 @Override public void render(GuiGraphics g,int mouseX,int mouseY,float partial){update();g.fill(0,0,width,height,0xF0141D27);g.fill(0,0,width,34,0xFF202D3C);g.fill(10,31,Math.min(width-110,170),33,0xFFE1AF50);var box=layout.canvas();var panel=layout.details();g.fill((int)box.x(),(int)box.y(),(int)(box.x()+box.width()),(int)(box.y()+box.height()),0xFF101820);g.fill((int)panel.x(),(int)panel.y(),(int)(panel.x()+panel.width()),(int)(panel.y()+panel.height()),0xEE243040);if(observed.nodes().isEmpty())g.drawWordWrap(font,Component.literal(observed.message()),(int)box.x()+12,(int)box.y()+16,(int)Math.max(1,box.width()-24),0xFFE0E5EC);else if(activeTab.equals("civilization_progress"))canvas(g,mouseX,mouseY);if(activeTab.equals("civilization_progress"))details(g);g.drawString(font,fit("Drag to pan  |  Wheel to zoom  |  Select a milestone",width-16),8,height-18,0xFFB3C1D0,true);super.render(g,mouseX,mouseY,partial);}
 private void canvas(GuiGraphics g,int mx,int my){var box=layout.canvas();g.enableScissor((int)box.x(),(int)box.y(),(int)(box.x()+box.width()),(int)(box.y()+box.height()));var p=g.pose();p.pushMatrix();try{p.translate((float)(box.x()+camera.panX()),(float)(box.y()+camera.panY()));p.scale((float)camera.zoom(),(float)camera.zoom());var bounds=ProgressCanvas.bounds(observed);for(var era:observed.eras()){g.fill((int)era.start(),(int)bounds.top(),(int)era.end(),(int)bounds.bottom(),0x50000000|era.background());g.fill((int)era.start(),(int)bounds.top(),(int)era.end(),(int)bounds.top()+3,0xFF000000|era.color());g.drawString(font,fit(era.title(),(int)(era.end()-era.start()-16)),(int)era.start()+8,(int)bounds.top()+12,0xFF000000|era.color(),true);}var nodes=new LinkedHashMap<String,ProgressView.Node>();for(var n:observed.nodes())nodes.put(n.id(),n);int lane=0;for(var edge:observed.connections()){boolean emphasis=edge.from().equals(selected)||edge.to().equals(selected);int color=emphasis?0xFFFFD782:edge.kind()==ProgressGraph.EdgeKind.VISUAL?0xFF697A90:0xFFA6BACF;var route=ProgressCanvas.route(edge,nodes,lane++);for(int i=1;i<route.size();i++)line(g,route.get(i-1),route.get(i),color,emphasis?2.5f:1.3f,edge.kind()==ProgressGraph.EdgeKind.VISUAL);var end=route.getLast();line(g,new ProgressGraph.Point(end.x()-5,end.y()-4),end,color,1.5f,false);line(g,new ProgressGraph.Point(end.x()-5,end.y()+4),end,color,1.5f,false);}var cursor=camera.world(mx,my);for(var n:observed.nodes()){var top=camera.screen(n.x(),n.y());var bottom=camera.screen(n.x()+ProgressGraph.NODE_WIDTH,n.y()+ProgressGraph.NODE_HEIGHT);if(bottom.x()<box.x()||top.x()>box.x()+box.width()||bottom.y()<box.y()||top.y()>box.y()+box.height())continue;int x=(int)n.x(),y=(int)n.y();int era=observed.eras().stream().filter(e->e.id().equals(n.era())).findFirst().orElseThrow().color();boolean hover=box.contains(mx,my)&&cursor.x()>=x&&cursor.x()<x+156&&cursor.y()>=y&&cursor.y()<y+52;g.fill(x-2,y-2,x+158,y+54,n.id().equals(selected)||hover?0xFFFFD782:0xFF000000|era);int fill=switch(n.state()){case COMPLETED->0xFF203E37;case AVAILABLE->0xFF30415A;case LOCKED->0xFF232A34;};g.fill(x,y,x+156,y+52,fill);var icon=BuiltInRegistries.ITEM.getValue(ResourceLocation.parse(n.icon()));g.renderItem(icon==null?new ItemStack(Items.PAPER):new ItemStack(icon),x+6,y+8);var lines=font.split(Component.literal(n.title()),122);for(int i=0;i<Math.min(2,lines.size());i++)g.drawString(font,lines.get(i),x+28,y+7+i*10,n.state()==ProgressView.State.LOCKED?0xFFBAC4D0:0xFFF5F7FA,true);g.drawString(font,label(n.state()),x+28,y+36,stateColor(n.state()),true);g.fill(x,y+49,x+156,y+52,0xFF000000|era);}}finally{p.popMatrix();g.disableScissor();}}
 private void line(GuiGraphics g,ProgressGraph.Point a,ProgressGraph.Point b,int color,float thickness,boolean dashed){double dx=b.x()-a.x(),dy=b.y()-a.y(),length=Math.hypot(dx,dy);if(length<.01)return;var sa=camera.screen(a.x(),a.y());var sb=camera.screen(b.x(),b.y());var box=layout.canvas();if(Math.max(sa.x(),sb.x())<box.x()||Math.min(sa.x(),sb.x())>box.x()+box.width()||Math.max(sa.y(),sb.y())<box.y()||Math.min(sa.y(),sb.y())>box.y()+box.height())return;var pose=g.pose();pose.pushMatrix();try{pose.translate((float)a.x(),(float)a.y());pose.rotate((float)Math.atan2(dy,dx));pose.scale((float)length,thickness);if(dashed){int count=Math.max(1,Math.min(24,(int)(length/10)));for(int i=0;i<count;i++){pose.pushMatrix();pose.translate(i/(float)count,0);pose.scale(.6f/count,1);g.fill(0,0,1,1,color);pose.popMatrix();}}else g.fill(0,0,1,1,color);}finally{pose.popMatrix();}}
 private void details(GuiGraphics g){var box=layout.details();var lines=new ArrayList<FormattedCharSequence>();var node=observed.nodes().stream().filter(n->n.id().equals(selected)).findFirst().orElse(null);int available=(int)Math.max(1,box.width()-20);if(node==null){add(lines,observed.title(),available);add(lines,"",available);add(lines,"Select a milestone to inspect shared progress.",available);add(lines,"Required links are solid. Visual-only links are dashed and never unlock anything.",available);add(lines,"Locked / Available / Completed",available);}else{add(lines,node.title(),available);add(lines,label(node.state())+"  •  "+node.category().name().toLowerCase(Locale.ROOT),available);add(lines,"",available);add(lines,node.description(),available);add(lines,"",available);if(!node.known())add(lines,"Shared state is not initialised; ask the teacher.",available);if(node.current()!=null)add(lines,"Shared value: "+node.current()+"; completed at "+node.targetMin()+(node.targetMin().equals(node.targetMax())?"":".."+node.targetMax()),available);if(node.placeholder())add(lines,"Future placeholder — not playable.",available);add(lines,"Required: ALL (AND)",available);if(node.requires().isEmpty())add(lines,"No node prerequisites.",available);for(var r:node.requires())add(lines,(r.completed()?"✓ ":"• ")+r.label(),available);if(!node.gatePassed())add(lines,"Other declared shared condition is pending.",available);add(lines,"Read-only. Completion uses server progression.",available);}detailMax=Math.max(0,lines.size()*11-(int)box.height()+16);detailScroll=Math.max(0,Math.min(detailScroll,detailMax));g.enableScissor((int)box.x()+4,(int)box.y()+4,(int)(box.x()+box.width()-4),(int)(box.y()+box.height()-4));try{for(int i=0;i<lines.size();i++)g.drawString(font,lines.get(i),(int)box.x()+10,(int)box.y()+10+i*11-detailScroll,0xFFE7EDF5,true);}finally{g.disableScissor();}}
 private void add(List<FormattedCharSequence> lines,String text,int width){if(text.isEmpty())lines.add(FormattedCharSequence.EMPTY);else lines.addAll(font.split(Component.literal(text),width));}
 private String fit(String text,int width){if(font.width(text)<=width)return text;return font.plainSubstrByWidth(text,Math.max(0,width-font.width("...")))+"...";}
 private static String label(ProgressView.State state){return switch(state){case LOCKED->"Locked";case AVAILABLE->"Available";case COMPLETED->"Completed";};}
 private static int stateColor(ProgressView.State state){return switch(state){case LOCKED->0xFFADB8C6;case AVAILABLE->0xFFFFD782;case COMPLETED->0xFF92DFC0;};}
 @Override public boolean mouseClicked(double x,double y,int button){if(super.mouseClicked(x,y,button))return true;if(layout.canvas().contains(x,y)&&(button==0||button==1)){dragging=true;if(button==0){var pos=camera.world(x,y);for(var n:observed.nodes())if(pos.x()>=n.x()&&pos.x()<n.x()+156&&pos.y()>=n.y()&&pos.y()<n.y()+52){selected=n.id();detailScroll=0;break;}}return true;}return false;}
 @Override public boolean mouseDragged(double x,double y,int button,double dx,double dy){if(dragging&&(button==0||button==1)){camera.pan(dx,dy);return true;}return super.mouseDragged(x,y,button,dx,dy);}
 @Override public boolean mouseReleased(double x,double y,int button){boolean was=dragging;dragging=false;return super.mouseReleased(x,y,button)||was;}
 @Override public boolean mouseScrolled(double x,double y,double horizontal,double vertical){if(layout.details().contains(x,y)){detailScroll=Math.max(0,Math.min(detailMax,detailScroll-(int)(vertical*22)));return true;}if(layout.canvas().contains(x,y)){camera.zoom(vertical,x,y);return true;}return super.mouseScrolled(x,y,horizontal,vertical);}
 @Override public boolean keyPressed(int key,int scan,int modifiers){if(key==GLFW.GLFW_KEY_HOME){camera.fit();return true;}if(key==GLFW.GLFW_KEY_LEFT||key==GLFW.GLFW_KEY_RIGHT||key==GLFW.GLFW_KEY_UP||key==GLFW.GLFW_KEY_DOWN){camera.pan(key==GLFW.GLFW_KEY_LEFT?32:key==GLFW.GLFW_KEY_RIGHT?-32:0,key==GLFW.GLFW_KEY_UP?32:key==GLFW.GLFW_KEY_DOWN?-32:0);return true;}return super.keyPressed(key,scan,modifiers);}
}
